const basePremiumForItems = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const withInitialAssessmentSurcharge = (basePremium: number): number =>
  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);

const quotePremium = (items: Item[]): number =>
  Math.round(
    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
  );

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quote.items) }] };
};
